return (function buildSourceRequests() {
  const config = { ...$input.first().json };
  for (const key of ['sparkyBaseUrl', 'obsidianBaseUrl']) {
    if (typeof config[key] !== 'string' ||
        !/^https:\/\/(?:[A-Za-z0-9.-]+|\[[A-Fa-f0-9:]+\])(?::[0-9]{1,5})?\/?$/.test(config[key])) {
      throw new Error(`${key} must be an HTTPS origin without credentials, path, query, or fragment.`);
    }
    config[key] = config[key].replace(/\/+$/, '');
  }
  if (!Number.isInteger(config.lookbackDays) || config.lookbackDays < 1 || config.lookbackDays > 31) {
    throw new Error('lookbackDays must be an integer from 1 to 31.');
  }
  if (typeof config.previewOnly !== 'boolean' || typeof config.createMissingNotes !== 'boolean') {
    throw new Error('previewOnly and createMissingNotes must be booleans.');
  }
  const parts = Object.fromEntries(new Intl.DateTimeFormat('en-CA', {
    timeZone: config.timezone, year: 'numeric', month: '2-digit', day: '2-digit',
  }).formatToParts(new Date()).map(part => [part.type, part.value]));
  const end = config.endDateOverride || `${parts.year}-${parts.month}-${parts.day}`;
  const endMs = Date.parse(`${end}T00:00:00Z`);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(end) || !Number.isFinite(endMs) ||
      new Date(endMs).toISOString().slice(0, 10) !== end) {
    throw new Error('endDateOverride must be blank or a real YYYY-MM-DD date.');
  }
  const today = `${parts.year}-${parts.month}-${parts.day}`;
  if (end > today) throw new Error('Future dates cannot be imported.');
  if (!/^_templates\/[^\\\r\n]+\.md$/.test(config.dailyTemplatePath) ||
      config.dailyTemplatePath.split('/').includes('..')) {
    throw new Error('dailyTemplatePath must identify a Markdown file under _templates/.');
  }
  const requests = [];
  for (let offset = config.lookbackDays - 1; offset >= 0; offset--) {
    const date = new Date(endMs - offset * 86400000).toISOString().slice(0, 10);
    const endpoints = {
      summary: `/daily-summary?date=${date}`,
      water: `/measurements/water-intake/${date}`,
      measurements: `/measurements/check-in-measurements-range/${date}/${date}`,
      sleep: `/sleep?startDate=${date}&endDate=${date}`,
    };
    for (const [kind, endpoint] of Object.entries(endpoints)) {
      requests.push({ json: { config, date, kind, url: `${config.sparkyBaseUrl}/api${endpoint}` } });
    }
  }
  return requests;
})();

return (function normalizeSourceData() {
  const requests = $('Build source requests').all();
  const responses = $input.all();
  if (responses.length !== requests.length) throw new Error('Unexpected number of SparkyFitness responses.');
  const days = new Map();
  const numeric = (value, label, minimum = 0) => {
    if ((typeof value !== 'number' && typeof value !== 'string') ||
        String(value).trim() === '' || !Number.isFinite(Number(value)) || Number(value) < minimum) {
      throw new Error(`${label}: expected a finite number >= ${minimum}.`);
    }
    return Number(value);
  };
  const dayString = value => {
    if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}(?:$|T)/.test(value)) {
      throw new Error('SparkyFitness returned an invalid entry_date.');
    }
    return value.slice(0, 10);
  };
  const round = (value, digits = 2) => Number(value.toFixed(digits));
  const cell = value => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;')
    .replace(/>/g, '&gt;').replace(/\\/g, '\\\\').replace(/[|[\]`*_]/g, '\\$&')
    .replace(/[\r\n]+/g, ' ');
  for (let i = 0; i < requests.length; i++) {
    const req = requests[i].json;
    const res = responses[i].json;
    if (res.statusCode !== 200 || !res.body || typeof res.body !== 'object') {
      throw new Error(`${req.kind} ${req.date}: expected a JSON 200 response, got ${res.statusCode}.`);
    }
    if (!days.has(req.date)) days.set(req.date, { config: req.config, date: req.date });
    days.get(req.date)[req.kind] = res.body;
  }
  return [...days.values()].map(day => {
    const { date, config, summary, water, measurements, sleep } = day;
    if (!Array.isArray(summary.foodEntries) || !summary.supplementTotals ||
        !summary.calorieBalance || !Array.isArray(measurements) || !Array.isArray(sleep)) {
      throw new Error(`${date}: response does not match SparkyFitness v1.9.0.`);
    }
    const fields = {};
    const issues = [];
    const entries = [];
    const seen = new Map();
    for (const entry of summary.foodEntries) {
      if (!entry || typeof entry.id !== 'string' || dayString(entry.entry_date) !== date) {
        throw new Error(`${date}: invalid or incorrectly dated food entry.`);
      }
      if (seen.has(entry.id)) {
        if (seen.get(entry.id) !== JSON.stringify(entry)) throw new Error(`${date}: conflicting duplicate food ID.`);
        continue;
      }
      seen.set(entry.id, JSON.stringify(entry));
      entries.push(entry);
    }
    const nutrients = {
      calories_kcal: 'calories', protein_g: 'protein', carbs_g: 'carbs',
      fat_g: 'fat', fiber_g: 'dietary_fiber',
    };
    const supplements = summary.supplementTotals;
    const hasSupplements = Object.values(supplements).some(value => typeof value === 'number' && value > 0) ||
      Object.values(supplements.custom_nutrients || {}).some(value => Number(value) > 0);
    const nutritionRecorded = entries.length > 0 || hasSupplements;
    let calculatedCalories;
    for (const [target, nutrient] of Object.entries(nutrients)) {
      const supplementTotal = numeric(supplements[nutrient], `${date} supplement ${nutrient}`);
      let total = 0;
      let complete = true;
      for (const entry of entries) {
        const source = entry.calories !== undefined || Object.keys(entry.custom_nutrients || {}).length > 0
          ? entry : entry.food_variants || (entry.foods && entry.foods.default_variant);
        if (!source || source[nutrient] == null) {
          complete = false;
          continue;
        }
        // SparkyFitness snapshots nutrients per reference serving, not per logged quantity.
        const reference = source.serving_size == null ? 100 : numeric(source.serving_size, 'serving_size');
        if (reference === 0) throw new Error(`${date}: serving_size cannot be zero.`);
        total += numeric(source[nutrient], nutrient) * numeric(entry.quantity, 'quantity') / reference;
      }
      total += supplementTotal;
      if (nutritionRecorded && complete) {
        fields[target] = round(total);
        if (target === 'calories_kcal') calculatedCalories = total;
      }
      if (nutritionRecorded && !complete) issues.push(`${target} withheld: one or more food snapshots lack this nutrient.`);
    }
    if (calculatedCalories !== undefined) {
      const reportedCalories = numeric(summary.calorieBalance.eaten, 'calorieBalance.eaten');
      const roundedCalories = Math.round(calculatedCalories);
      if (roundedCalories !== reportedCalories) {
        throw new Error(`${date}: calculated calories disagree with SparkyFitness's daily total (calculated ${calculatedCalories} kcal; rounded ${roundedCalories} kcal; reported ${reportedCalories} kcal). No notes will be written.`);
      }
    }
    const waterMl = numeric(water.water_ml, `${date} water_ml`);
    if (waterMl > 0) fields.water_ml = round(waterMl);
    // This endpoint returns zero even without a log; zero alone is not an observation.
    if (waterMl === 0) issues.push('Water is unrecorded or zero; no water_ml value is inferred.');
    for (const row of measurements) {
      if (dayString(row.entry_date) !== date) throw new Error(`${date}: measurement belongs to another day.`);
    }
    for (const [target, source] of [['weight_kg', 'weight'], ['steps', 'steps']]) {
      const values = [...new Set(measurements.filter(row => row[source] != null)
        .map(row => numeric(row[source], `${date} ${source}`)))];
      if (values.length > 1) {
        issues.push(`${target} withheld: conflicting same-day check-ins.`);
      } else if (values.length === 1) {
        if (target === 'weight_kg' && values[0] === 0) {
          issues.push('weight_kg withheld: zero is not a valid weight.');
        } else {
          if (target === 'steps' && !Number.isSafeInteger(values[0])) throw new Error(`${date}: steps must be an integer.`);
          fields[target] = target === 'steps' ? values[0] : round(values[0]);
        }
      }
    }
    const sleepRows = config.sleepSource ? sleep.filter(row => row.source === config.sleepSource) : sleep;
    if (config.sleepSource && sleep.length && !sleepRows.length) {
      issues.push('sleep_hours withheld: the configured sleep source has no record.');
    }
    const candidates = new Map();
    let invalidSleep = false;
    for (const row of sleepRows) {
      const start = Date.parse(row.bedtime);
      const end = Date.parse(row.wake_time);
      const seconds = numeric(row.time_asleep_in_seconds ?? row.duration_in_seconds, 'sleep duration');
      const hasOffset = value => typeof value === 'string' && /(?:Z|[+-]\d{2}:\d{2})$/.test(value);
      if (!hasOffset(row.bedtime) || !hasOffset(row.wake_time) || !Number.isFinite(start) ||
          !Number.isFinite(end) || end <= start || seconds <= 0 || seconds * 1000 > end - start) {
        invalidSleep = true;
        continue;
      }
      let wakeDate;
      if (!row.record_timezone && row.record_utc_offset_minutes != null) {
        const offset = Number(row.record_utc_offset_minutes);
        if (!Number.isFinite(offset) || Math.abs(offset) > 840) throw new Error('Invalid recorded sleep UTC offset.');
        wakeDate = new Date(end + offset * 60000).toISOString().slice(0, 10);
      } else {
        const parts = Object.fromEntries(new Intl.DateTimeFormat('en-CA', {
          timeZone: row.record_timezone || config.timezone, year: 'numeric', month: '2-digit', day: '2-digit',
        }).formatToParts(new Date(end)).map(part => [part.type, part.value]));
        wakeDate = `${parts.year}-${parts.month}-${parts.day}`;
      }
      if (dayString(row.entry_date) !== date || wakeDate !== date) {
        invalidSleep = true;
        continue;
      }
      candidates.set(`${start}/${end}/${seconds}`, { seconds, source: row.source });
    }
    if (invalidSleep || candidates.size > 1) {
      issues.push('sleep_hours withheld: invalid, incorrectly dated, or conflicting sleep records. No durations are added together.');
    } else if (candidates.size === 1) {
      fields.sleep_hours = round([...candidates.values()][0].seconds / 3600);
    }
    const labels = {
      calories_kcal: ['Energy', 'kcal'], protein_g: ['Protein', 'g'], carbs_g: ['Carbohydrate', 'g'],
      fat_g: ['Fat', 'g'], fiber_g: ['Fibre', 'g'], water_ml: ['Water', 'ml'],
      weight_kg: ['Weight', 'kg'], steps: ['Steps', ''], sleep_hours: ['Sleep', 'hours'],
    };
    const lines = [
      '<!-- sparkyfitness:start -->', '## SparkyFitness', '',
      `Recorded date: ${date} | [Source](${config.sparkyBaseUrl}/)`, '',
      'Logged totals only; missing values do not mean zero or a completed day.', '',
      '| Metric | Recorded value |', '| --- | --- |',
    ];
    for (const [key, [label, unit]] of Object.entries(labels)) {
      if (fields[key] !== undefined) lines.push(`| ${label} | ${fields[key]}${unit ? ` ${unit}` : ''} |`);
    }
    if (Object.keys(fields).length === 0) lines.push('| Observations | None available |');
    const absent = Object.entries(labels).filter(([key]) => fields[key] === undefined).map(([, value]) => value[0]);
    if (absent.length) lines.push('', `Not available: ${absent.join(', ')}.`);
    if (entries.length) {
      lines.push('', '### Food diary', '', '| Meal | Time | Food | Quantity |',
        '| --- | --- | --- | --- |');
      for (const entry of entries) {
        lines.push(`| ${cell(entry.meal_type || 'Unspecified')} | ${cell(entry.entry_time || '')} | ${cell(entry.food_name || '[name not supplied]')} | ${numeric(entry.quantity, 'quantity')} ${cell(entry.unit || '')} |`);
      }
    }
    if (hasSupplements) lines.push('', 'Nutrition totals include recorded supplements.');
    if (fields.sleep_hours !== undefined) {
      lines.push('', `Sleep source: ${cell([...candidates.values()][0].source || 'not supplied')}.`);
    }
    if (issues.length) lines.push('', '### Data notes', '', ...issues.map(issue => `- ${issue}`));
    lines.push('<!-- sparkyfitness:end -->');
    return { json: { config, date, fields, issues, hasData: Object.keys(fields).length > 0,
      managedBlock: lines.join('\n') } };
  });
})();

return (function buildVaultReads() {
  const plans = $input.all().map(item => item.json);
  const config = plans[0].config;
  const encodePath = value => value.split('/').map(encodeURIComponent).join('/');
  const requests = [{ json: { kind: 'template', path: config.dailyTemplatePath,
    url: `${config.obsidianBaseUrl}/vault/${encodePath(config.dailyTemplatePath)}` } }];
  for (const plan of plans) {
    const year = plan.date.slice(0, 4);
    const month = plan.date.slice(0, 7);
    for (const candidate of [`${year}/${plan.date}.md`, `${year}/${month}/${plan.date}.md`,
      `z_archive/${year}/${month}/${plan.date}.md`]) {
      requests.push({ json: { kind: 'note', date: plan.date, path: candidate, plan,
        url: `${config.obsidianBaseUrl}/vault/${encodePath(candidate)}` } });
    }
  }
  return requests;
})();

function isSyncField(key) {
  return /^(?:hardcover_|sparkyfitness_|kindle-)/i.test(key);
}

function isSyncObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  // n8n secure mode stubs prototype inspection; validate record shape instead.
  if (Object.prototype.toString.call(value) !== '[object Object]') return false;
  if (!Object.hasOwn(value, 'constructor') && value.constructor !== undefined &&
      (typeof value.constructor !== 'function' || value.constructor.name !== 'Object')) return false;
  for (const key in value) {
    if (!Object.hasOwn(value, key)) return false;
  }
  return true;
}

function syncJson(value) {
  const normalize = item => {
    if (item === null || typeof item === 'string' || typeof item === 'boolean') return item;
    if (typeof item === 'number' && Number.isFinite(item)) return item;
    if (Array.isArray(item)) return item.map(normalize);
    if (isSyncObject(item)) {
      return Object.fromEntries(Object.keys(item).sort().map(key => [key, normalize(item[key])]));
    }
    throw new Error('External-sync metadata must contain only JSON values.');
  };
  return JSON.stringify(normalize(value)).replace(/</g, '\\u003c').replace(/>/g, '\\u003e');
}

function validateSyncProperties(properties) {
  if (!isSyncObject(properties)) {
    throw new Error('External-sync properties must be a JSON object.');
  }
  const seen = new Set();
  for (const key of Object.keys(properties)) {
    if (!isSyncField(key) || seen.has(key.toLowerCase())) {
      throw new Error(`Unknown or case-conflicting external-sync property: ${key}`);
    }
    seen.add(key.toLowerCase());
  }
  syncJson(properties);
  return properties;
}

function readSyncMetadata(content) {
  const marker = '<!-- external-sync';
  const count = content.split(marker).length - 1;
  if (!count) return { properties: {}, start: -1, end: -1 };
  const matches = [...content.matchAll(/^<!-- external-sync\r?\n([\s\S]*?)\r?\n-->(?=\r?\n|$)/gm)];
  if (count !== 1 || matches.length !== 1) {
    throw new Error('Malformed or repeated external-sync comment; refusing to edit.');
  }
  const match = matches[0];
  const before = content.slice(0, match.index);
  const opening = /^\uFEFF?---[ \t]*\r?\n/.exec(content);
  const closing = opening && /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(content.slice(opening[0].length));
  if (opening && (!closing || match.index < opening[0].length + closing.index + closing[0].length)) {
    throw new Error('External-sync comments must be outside frontmatter.');
  }
  let fence = null;
  for (const line of before.split(/\r?\n/)) {
    const token = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line);
    if (!token) continue;
    if (!fence) fence = { character: token[1][0], length: token[1].length };
    else if (token[1][0] === fence.character && token[1].length >= fence.length && !token[2].trim()) fence = null;
  }
  if (fence || before.lastIndexOf('<!--') > before.lastIndexOf('-->')) {
    throw new Error('External-sync comments must not be inside code fences or other comments.');
  }
  let payload;
  try {
    payload = JSON.parse(match[1]);
  } catch (error) {
    throw new Error(`Invalid external-sync JSON: ${error.message}`);
  }
  if (!payload || payload.version !== 1 || Object.keys(payload).sort().join(',') !== 'properties,version') {
    throw new Error('Unsupported external-sync schema; expected version 1 and properties.');
  }
  return { properties: validateSyncProperties(payload.properties), start: match.index,
    end: match.index + match[0].length };
}

function mergeSyncProperties(content, metadata) {
  const properties = { ...readSyncMetadata(content).properties };
  for (const [key, value] of Object.entries(metadata)) {
    if (!isSyncField(key)) continue;
    const existing = Object.keys(properties).find(name => name.toLowerCase() === key.toLowerCase());
    if (existing && syncJson(properties[existing]) !== syncJson(value)) {
      throw new Error(`Legacy frontmatter and external-sync comment disagree for ${key}.`);
    }
    if (!existing) properties[key] = value;
  }
  return validateSyncProperties(properties);
}

function writeSyncMetadata(content, properties) {
  validateSyncProperties(properties);
  const previous = readSyncMetadata(content);
  if (!Object.keys(properties).length && previous.start < 0) return content;
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const comment = `<!-- external-sync${eol}${syncJson({ version: 1, properties })}${eol}-->`;
  const updated = previous.start >= 0
    ? content.slice(0, previous.start) + comment + content.slice(previous.end)
    : content + (content.endsWith(eol + eol) ? '' : content.endsWith('\n') ? eol : eol + eol) + comment + eol;
  readSyncMetadata(updated);
  return updated;
}
return (function prepareNoteUpdates() {
  const requests = $('Build vault reads').all();
  const responses = $input.all();
  if (requests.length !== responses.length) throw new Error('Unexpected number of Obsidian read responses.');
  const records = requests.map((item, index) => ({ ...item.json, response: responses[index].json }));
  for (const record of records) {
    if (![200, 404].includes(record.response.statusCode)) {
      throw new Error(`Obsidian ${record.path}: HTTP ${record.response.statusCode}. Check the address, API key, and TLS trust.`);
    }
    if (record.response.statusCode === 200 &&
        (!record.response.body || typeof record.response.body.content !== 'string' ||
         !record.response.body.frontmatter || typeof record.response.body.frontmatter !== 'object')) {
      throw new Error(`Obsidian ${record.path}: expected application/vnd.olrapi.note+json.`);
    }
  }
  const template = records.find(record => record.kind === 'template');
  const allowed = new Set(['calories_kcal', 'protein_g', 'carbs_g', 'fat_g', 'fiber_g',
    'water_ml', 'weight_kg', 'steps', 'sleep_hours']);
  const updateFrontmatter = (content, values, removals, metadata) => {
    const bom = content.startsWith('\uFEFF') ? '\uFEFF' : '';
    const text = content.slice(bom.length);
    const eol = content.includes('\r\n') ? '\r\n' : '\n';
    const opening = /^---[ \t]*\r?\n/.exec(text);
    let body = '';
    let tail = text;
    let head = `---${eol}`;
    let closing = `---${eol}`;
    if (opening) {
      const rest = text.slice(opening[0].length);
      const end = /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(rest);
      if (!end) throw new Error('Unclosed YAML frontmatter; refusing to edit the note.');
      body = rest.slice(0, end.index);
      head = opening[0];
      closing = end[0];
      tail = rest.slice(end.index + end[0].length);
    }
    const lines = body.match(/[^\n]*(?:\n|$)/g)?.filter(line => line !== '') || [];
    const commentOrBlank = line => /^\s*(?:#.*)?$/.test(line.replace(/\r?\n$/, ''));
    const touched = new Set([...Object.keys(values), ...removals]);
    const found = new Set();
    for (let i = lines.length - 1; i >= 0; i--) {
      const key = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)/.exec(lines[i].replace(/\r?\n$/, ''));
      if (!key || !touched.has(key[1])) continue;
      if (found.has(key[1])) throw new Error(`Duplicate YAML property ${key[1]}; refusing to edit.`);
      found.add(key[1]);
      const old = metadata[key[1]];
      if (old != null && typeof old !== 'number' && !['sparkyfitness_fields', 'sparkyfitness_date'].includes(key[1])) {
        throw new Error(`Unexpected type for ${key[1]}; refusing to replace user-authored structured content.`);
      }
      let end = i + 1;
      while (end < lines.length && /^(?:[ \t]+\S|-[ \t])/.test(lines[end])) end++;
      const replacement = Object.hasOwn(values, key[1])
        ? [`${key[1]}: ${JSON.stringify(values[key[1]])}${eol}`] : [];
      const rawValue = lines[i].replace(/\r?\n$/, '').slice(key[1].length + 1)
        .replace(/(?:^|\s+)#.*$/, '').trim();
      if (key[1] === 'sparkyfitness_fields') {
        const ownerKey = raw => {
          const match = /^(?:"([A-Za-z_]+)"|'([A-Za-z_]+)'|([A-Za-z_]+))$/.exec(raw.trim());
          if (!match) throw new Error('Unsupported ownership list item.');
          return match[1] || match[2] || match[3];
        };
        let rawFields;
        if (rawValue === '') {
          let cursor = i + 1;
          let lastValueLine = i;
          while (cursor < lines.length) {
            if (commentOrBlank(lines[cursor])) {
              cursor++;
              continue;
            }
            if (/^\s*-[ \t]/.test(lines[cursor])) {
              lastValueLine = cursor++;
              continue;
            }
            break;
          }
          end = lastValueLine + 1;
          rawFields = end === i + 1 ? null : lines.slice(i + 1, end).filter(line => !commentOrBlank(line))
            .map(line => ownerKey(line.replace(/^\s*-[ \t]+/, '').replace(/\s+#.*$/, '').trim()));
          replacement.push(...lines.slice(i + 1, end).filter(commentOrBlank));
        } else if (!/^\[.*\]$/.test(rawValue)) {
          throw new Error('Unsupported multiline ownership list; use a standard YAML list.');
        } else {
          const items = rawValue.slice(1, -1).trim();
          rawFields = items ? items.replace(/,[ \t]*$/, '').split(',').map(ownerKey) : [];
        }
        if (syncJson(rawFields) !== syncJson(metadata[key[1]])) {
          throw new Error('Ownership YAML disagrees with the Obsidian metadata cache; wait for indexing and rerun.');
        }
      } else {
        const scalar = key[1] === 'sparkyfitness_date'
          ? /^(?:"\d{4}-\d{2}-\d{2}"|'\d{4}-\d{2}-\d{2}'|\d{4}-\d{2}-\d{2})$/
          : /^(?:null|~|[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?)?$/;
        if (!scalar.test(rawValue) ||
            lines.slice(i + 1, end).some(line => !commentOrBlank(line))) {
          throw new Error(`Nonstandard YAML value for ${key[1]}; refusing to rewrite structured content.`);
        }
        if (key[1] === 'sparkyfitness_date' &&
            rawValue.replace(/^["']|["']$/g, '') !== metadata[key[1]]) {
          throw new Error('Ownership date YAML disagrees with the Obsidian metadata cache; wait for indexing and rerun.');
        }
        end = i + 1;
      }
      if (['sparkyfitness_fields', 'sparkyfitness_date'].includes(key[1]) && !Object.hasOwn(values, key[1])) {
        const comment = /[ \t]+(#.*?)(?:\r?\n)?$/.exec(lines[i]);
        if (comment) replacement.unshift(comment[1] + eol);
      }
      lines.splice(i, end - i, ...replacement);
    }
    for (const key of touched) {
      if (Object.hasOwn(metadata, key) && !found.has(key)) {
        throw new Error(`Nonstandard or quoted YAML property ${key}; edit it manually before syncing.`);
      }
    }
    for (const [key, value] of Object.entries(values)) {
      if (!found.has(key)) lines.push(`${key}: ${JSON.stringify(value)}${eol}`);
    }
    return bom + head + lines.join('') + closing + tail;
  };
  const updateBlock = (content, block) => {
    const startMarker = '<!-- sparkyfitness:start -->';
