  const updateFrontmatter = (content, values, removals, metadata) => {
    const bom = content.startsWith('\uFEFF') ? '\uFEFF' : '';
    const text = content.slice(bom.length);
    const eol = content.includes('\r\n') ? '\r\n' : '\n';
    const opening = /^---[ \t]*\r?\n/.exec(text);
    let body = '';
    let tail = text;
    let head = `---${eol}`;
    let closing = `---${eol}`;
    if (opening) {
      const rest = text.slice(opening[0].length);
      const end = /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(rest);
      if (!end) throw new Error('Unclosed YAML frontmatter; refusing to edit the note.');
      body = rest.slice(0, end.index);
      head = opening[0];
      closing = end[0];
      tail = rest.slice(end.index + end[0].length);
    }
    const lines = body.match(/[^\n]*(?:\n|$)/g)?.filter(line => line !== '') || [];
    const commentOrBlank = line => /^\s*(?:#.*)?$/.test(line.replace(/\r?\n$/, ''));
    const touched = new Set([...Object.keys(values), ...removals]);
    const found = new Set();
    for (let i = lines.length - 1; i >= 0; i--) {
      const key = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)/.exec(lines[i].replace(/\r?\n$/, ''));
      if (!key || !touched.has(key[1])) continue;
      if (found.has(key[1])) throw new Error(`Duplicate YAML property ${key[1]}; refusing to edit.`);
      found.add(key[1]);
      const old = metadata[key[1]];
      if (old != null && typeof old !== 'number' && !['sparkyfitness_fields', 'sparkyfitness_date'].includes(key[1])) {
        throw new Error(`Unexpected type for ${key[1]}; refusing to replace user-authored structured content.`);
      }
      let end = i + 1;
      while (end < lines.length && /^(?:[ \t]+\S|-[ \t])/.test(lines[end])) end++;
      const replacement = Object.hasOwn(values, key[1])
        ? [`${key[1]}: ${JSON.stringify(values[key[1]])}${eol}`] : [];
      const rawValue = lines[i].replace(/\r?\n$/, '').slice(key[1].length + 1)
        .replace(/(?:^|\s+)#.*$/, '').trim();
      if (key[1] === 'sparkyfitness_fields') {
        const ownerKey = raw => {
          const match = /^(?:"([A-Za-z_]+)"|'([A-Za-z_]+)'|([A-Za-z_]+))$/.exec(raw.trim());
          if (!match) throw new Error('Unsupported ownership list item.');
          return match[1] || match[2] || match[3];
        };
        let rawFields;
        if (rawValue === '') {
          let cursor = i + 1;
          let lastValueLine = i;
          while (cursor < lines.length) {
            if (commentOrBlank(lines[cursor])) {
              cursor++;
              continue;
            }
            if (/^\s*-[ \t]/.test(lines[cursor])) {
              lastValueLine = cursor++;
              continue;
            }
            break;
          }
          end = lastValueLine + 1;
          rawFields = end === i + 1 ? null : lines.slice(i + 1, end).filter(line => !commentOrBlank(line))
            .map(line => ownerKey(line.replace(/^\s*-[ \t]+/, '').replace(/\s+#.*$/, '').trim()));
          replacement.push(...lines.slice(i + 1, end).filter(commentOrBlank));
        } else if (!/^\[.*\]$/.test(rawValue)) {
          throw new Error('Unsupported multiline ownership list; use a standard YAML list.');
        } else {
          const items = rawValue.slice(1, -1).trim();
          rawFields = items ? items.replace(/,[ \t]*$/, '').split(',').map(ownerKey) : [];
        }
        if (syncJson(rawFields) !== syncJson(metadata[key[1]])) {
          throw new Error('Ownership YAML disagrees with the Obsidian metadata cache; wait for indexing and rerun.');
        }
      } else {
        const scalar = key[1] === 'sparkyfitness_date'
          ? /^(?:"\d{4}-\d{2}-\d{2}"|'\d{4}-\d{2}-\d{2}'|\d{4}-\d{2}-\d{2})$/
          : /^(?:null|~|[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?)?$/;
        if (!scalar.test(rawValue) ||
            lines.slice(i + 1, end).some(line => !commentOrBlank(line))) {
          throw new Error(`Nonstandard YAML value for ${key[1]}; refusing to rewrite structured content.`);
        }
        if (key[1] === 'sparkyfitness_date' &&
            rawValue.replace(/^["']|["']$/g, '') !== metadata[key[1]]) {
          throw new Error('Ownership date YAML disagrees with the Obsidian metadata cache; wait for indexing and rerun.');
        }
        end = i + 1;
      }
      if (['sparkyfitness_fields', 'sparkyfitness_date'].includes(key[1]) && !Object.hasOwn(values, key[1])) {
        const comment = /[ \t]+(#.*?)(?:\r?\n)?$/.exec(lines[i]);
        if (comment) replacement.unshift(comment[1] + eol);
      }
      lines.splice(i, end - i, ...replacement);
    }
    for (const key of touched) {
      if (Object.hasOwn(metadata, key) && !found.has(key)) {
        throw new Error(`Nonstandard or quoted YAML property ${key}; edit it manually before syncing.`);
      }
    }
    for (const [key, value] of Object.entries(values)) {
      if (!found.has(key)) lines.push(`${key}: ${JSON.stringify(value)}${eol}`);
    }
    return bom + head + lines.join('') + closing + tail;
  };
  const updateBlock = (content, block) => {
    const startMarker = '<!-- sparkyfitness:start -->';
    const endMarker = '<!-- sparkyfitness:end -->';
    const starts = content.split(startMarker).length - 1;
    const ends = content.split(endMarker).length - 1;
    const eol = content.includes('\r\n') ? '\r\n' : '\n';
    const replacement = block.replace(/\n/g, eol);
    if (starts === 0 && ends === 0) {
      return content + (content.endsWith('\n') ? eol : eol + eol) + replacement + eol;
    }
    const start = content.indexOf(startMarker);
    const end = content.indexOf(endMarker);
    if (starts !== 1 || ends !== 1 || end < start ||
        (start > 0 && content[start - 1] !== '\n') ||
        (end > 0 && content[end - 1] !== '\n')) {
      throw new Error('Malformed or repeated SparkyFitness markers; refusing to overwrite the note.');
    }
    return content.slice(0, start) + replacement + content.slice(end + endMarker.length);
  };
  const output = [];
  const dates = [...new Set(records.filter(record => record.kind === 'note').map(record => record.date))];
  for (const date of dates) {
    const candidates = records.filter(record => record.kind === 'note' && record.date === date);
    const existing = candidates.filter(record => record.response.statusCode === 200);
    if (existing.length > 1) throw new Error(`${date}: multiple notes exist (${existing.map(record => record.path).join(', ')}). Resolve the duplicate first.`);
    const plan = candidates[0].plan;
    const note = existing[0] || candidates[0];
    const metadata = existing.length ? note.response.body.frontmatter : {};
    const syncProperties = mergeSyncProperties(existing.length ? note.response.body.content : '', metadata);
    const previous = Object.hasOwn(syncProperties, 'sparkyfitness_fields') ? syncProperties.sparkyfitness_fields : [];
    if (!Array.isArray(previous) || previous.some(key => !allowed.has(key)) ||
        new Set(previous).size !== previous.length) {
      throw new Error(`${date}: invalid sparkyfitness_fields ownership metadata.`);
    }
    if ((previous.length || Object.hasOwn(syncProperties, 'sparkyfitness_date')) &&
        syncProperties.sparkyfitness_date !== date) {
      throw new Error(`${date}: ownership date does not match the note filename.`);
    }
    const base = { config: plan.config, date, path: note.path, url: note.url,
      fields: plan.fields, issues: plan.issues, managedBlock: plan.managedBlock };
    const legacy = ['sparkyfitness_fields', 'sparkyfitness_date'].filter(key => Object.hasOwn(metadata, key));
    if ((!plan.hasData && previous.length === 0 && !legacy.length) || (!existing.length && !plan.config.createMissingNotes)) {
      output.push({ json: { ...base, action: !plan.hasData ? 'no-data' : 'missing-note', changes: {} } });
      continue;
    }
    let original;
    if (existing.length) {
      original = note.response.body.content;
    } else {
      if (template.response.statusCode !== 200) throw new Error('Cannot create a note: the daily template is missing.');
      if (Object.keys(template.response.body.frontmatter).some(isSyncField) ||
          Object.keys(mergeSyncProperties(template.response.body.content, {})).length) {
        throw new Error('The daily template must not contain external sync bookkeeping.');
      }
      original = template.response.body.content.replace(/\{\{date:YYYY-MM-DD\}\}/g, date);
      if (/\{\{[\s\S]*?\}\}|<%/.test(original)) throw new Error('Daily template has unsupported dynamic placeholders.');
    }
    const removals = previous.filter(key => !Object.hasOwn(plan.fields, key));
    const cleaned = updateFrontmatter(original, plan.fields, [...removals, ...legacy], metadata);
    const updated = writeSyncMetadata(updateBlock(cleaned, plan.managedBlock),
      { ...syncProperties, sparkyfitness_fields: Object.keys(plan.fields).sort(), sparkyfitness_date: date });
    const headers = { 'Content-Type': 'text/markdown' };
    if (existing.length) {
      const tag = note.response.body.version || note.response.headers?.etag || note.response.headers?.ETag;
      if (typeof tag !== 'string' || !tag) throw new Error('Obsidian must provide an ETag/version for safe conditional writes.');
      headers['If-Match'] = tag;
    } else {
      headers['If-None-Match'] = '*';
    }
    const changes = {};
    for (const key of [...Object.keys(plan.fields), ...removals]) {
      const before = metadata[key] ?? null;
      const after = plan.fields[key] ?? null;
      if (before !== after) changes[key] = { before, after };
    }
    output.push({ json: { ...base, action: existing.length ? (updated === original ? 'unchanged' : 'update') : 'create',
      changes, headers, proposedContent: updated } });
  }
  return output;
})();

return (function previewResults() {
  return $input.all().map(item => {
    const { date, path, action, fields, changes, issues, managedBlock, config } = item.json;
    return { json: { date, path, action, previewOnly: config.previewOnly, fields, changes, issues,
      managedBlock, note: ['update', 'create'].includes(action)
        ? 'Preview only: no note has been written.' : 'No write required.' } };
  });
})();

return (function verifyWrites() {
  const expected = $('Write enabled?').all(0);
  const actual = $input.all();
  if (expected.length !== actual.length) throw new Error('Unexpected number of verification responses.');
  return actual.map((item, index) => {
    const plan = expected[index].json;
    if (item.json.statusCode !== 200 || item.json.body !== plan.proposedContent) {
      throw new Error(`${plan.path}: read-back differs from the submitted note. Inspect for concurrent/Seafile edits; nothing will be overwritten again in this run.`);
    }
    return { json: { date: plan.date, path: plan.path, action: plan.action,
      verified: true, fields: plan.fields, issues: plan.issues } };
  });
})();
